sys_script_include.script:
var NeedItUtils = Class.create();
NeedItUtils.prototype = {
    initialize: function() {
    },

    isDatePast: function(strDate) {
        // Create GlideDateTime objects for the current date and the passed in date
        var rightnow = new GlideDateTime();
        var testdate = new GlideDateTime(strDate);

        // Compare only the date part, not the time
        var todayDate = rightnow.getLocalDate();
        var testDateOnly = testdate.getLocalDate();

        // If the passed in date is before today, return true
        if (testDateOnly.compareTo(todayDate) < 0) {
            return true;
        } else {
            return false;
        }
    },

    isDateToday: function(strDate) {
        // Create GlideDateTime objects for today and the passed in date
        var rightnow = new GlideDateTime();
        var testdate = new GlideDateTime(strDate);

        // Compare only the date part, not the time
        var todayDate = rightnow.getLocalDate();
        var testDateOnly = testdate.getLocalDate();

        // If the passed in date is today, return true
        if (testDateOnly.compareTo(todayDate) == 0) {
            return true;
        } else {
            return false;
        }
    },

    type: 'NeedItUtils'
};
